-- Spartans — Sentinel's real club list (2026–27 club sheet), 2026-11-18.
-- Run after 0021.
--
--   • blurbs may now run to 2000 characters (the sheet's longest is ~1400)
--   • gc_code   the Google Classroom code to join, shown on the club's page
--   • is_new    new this year, shown as "New" in Add programs
--   • the placeholder clubs from the built-in list that the real sheet
--     replaces are switched off (only matters if seed/clubs.sql's old
--     version was run)
--   • then all 93 real clubs go in, or are refreshed if already there
-- The rows are generated from src/clubList.ts (scripts/clubs-sql.mjs), which
-- also writes supabase/seed/clubs.sql to re-run later. Staff edit the live
-- list in App Club → Clubs & programs.

-- 0021 makes the clubs table; stop with a clear message if it isn't there.
do $$ begin
  if to_regclass('public.clubs') is null then
    raise exception 'The clubs table is missing: run 0021_clubs_and_program_posts.sql first, then this file.';
  end if;
end $$;

alter table clubs drop constraint if exists clubs_blurb_check;
alter table clubs add constraint clubs_blurb_check check (char_length(blurb) <= 2000);
alter table clubs add column if not exists gc_code text check (char_length(gc_code) <= 20);
alter table clubs add column if not exists is_new boolean not null default false;

update clubs set active = false
where lower(trim(name)) in ('science club', 'debate club', 'model un', 'chess club', 'math club', 'multicultural club', 'rotary interact club');

with v(name, kind, blurb, meets, room, sponsor, gc_code, is_new) as (values
  ('Aerial Photography Club', 'club', 'The Aerial Photography Club at Sentinel is a one-of-a-kind program and the first of its kind in the district, combining aerial photography with aviation education by teaching young pilots how to pursue their licenses. The club supports Sentinel by providing high-quality aerial photography for school websites, presentations, and promotional materials. Due to its success, the program has expanded to include clubs at both Sentinel and Rockridge.', 'Lunch on the field, day TBD', 'Field', 'Mr. Anderson', '3qdxpbb', false),
  ('AI Club', 'club', null, null, null, 'Mr. Addis', null, false),
  ('Art Club', 'club', 'Art Club is an encouraging place where people of any level can come to learn about art and create their own masterpieces. This year, our main objective will be to teach basic principles of drawing and art by participating in different activities and classes. We hope to end up creating and painting a mural at an elementary school that has been under-resourced in our district. Join us if you are interested in being part of the creation process!', 'Biweekly Tuesdays at lunch', 'Room 151', 'Ms. Hambly', 'ipgwbhkx', false),
  ('Art for Wellness Club', 'club', null, 'Day TBD', 'Room 153A', 'Ms. Tabone', null, false),
  ('ASL (American Sign Language) Club', 'club', 'ASL Club is a space to learn American Sign Language, practice communicating through ASL, and explore Deaf culture and community. Through weekly meetings in Room 210A, members will learn commonly used signs, practice basic ASL conversations and activities, and discover how facial expressions, body language, and other non-manual signals contribute to communication in ASL. No prior ASL experience is required!', 'Thursdays at lunch', 'Room 210A', 'Ms. Curtin', 'q6ioilgc', true),
  ('The Athlete Access Foundation', 'club', 'The Athlete Access Foundation aims to remove financial barriers preventing young athletes in British Columbia from competing and pursuing their sport. Through financial assistance, mentorship, and community support, we help dedicated athletes pursue opportunities that would otherwise be limited by financial circumstances. Join our club to earn volunteer hours through fundraisers, apply for executive positions, and help make a change by supporting underprivileged athletes!', 'Biweekly Mondays at lunch', 'Room 310', 'Ms. Gagliano', 'tbnuvkav', true),
  ('Sentinel Badminton Community Club', 'club', 'The Sentinel Badminton Community Club offers a safe, casual space for badminton enthusiasts to meet and socialize, shares local and international badminton news (e.g., tournaments, rule changes, international rankings), and encourages physical activity and healthy badminton habits.', 'Mondays at FIT', 'Gym (non-bleacher side)', 'Ms. Bauck', 'jcffvubm', true),
  ('Best Buddies', 'club', null, 'Tuesdays at lunch', 'Room 259', 'Ms. Chappell & Ms. Willms', null, false),
  ('Berkeley Math Tournament (BMT) Club', 'club', 'The Berkeley Math Tournament (BMT) Club prepares students for an online team competition hosted by UC Berkeley in January. Join us to explore challenging math problems, build problem-solving skills, and meet others who enjoy math!', 'October 28 at lunch', 'Room 261', 'Ms. Jamieson', 'ebnf53u', false),
  ('Black Excellence Council', 'club', null, null, null, 'Mr. Obeck & Mr. Dadisso', null, true),
  ('Sentinel Book Club', 'club', 'Have you run out of books to add to your TBR? Have you hit a reading block? The Sentinel Book Club is the solution you need to all these problems. Meet people with the same passion and goal of reading, and converse or exchange book suggestions as we discuss weekly prompts on books. Additionally, we''ll have field trips to libraries/bookstores, afternoon tea meetings (we indulge in treats and tea while reading), dedicated silent reading time, and more!', 'Fridays at lunch', 'Room 206', 'Mr. McLean', '4a4musok', false),
  ('Boys Club Network', 'club', 'Boys Club Network is a mentorship organization to help young men to be better men. Through positive role models, mental-health resources, and a community that shows up, we help young men build resilience, self-worth, and a sense of belonging. We make sure that boys have a safe space to share in without feeling judged or the fear of things getting out.', 'Wednesdays at lunch', 'Room 323', 'Mr. Finch, Mr. Ahmelich & Mr. Dadisso', '652ibdk', false),
  ('Sentinel Business Club', 'club', null, 'Biweekly Fridays at lunch', 'Room 358', 'Mr. Demers', null, true),
  ('Business Startup Club', 'club', 'Students will develop their business startup ideas, learn to create business plans, and explore branding and product development. Through monthly competitions, members will present their business ideas and compete for prizes.', 'Biweekly Fridays at lunch', 'Room 258', 'Mr. Demers', '2lkcskg', true),
  ('Care Crafts Project', 'club', 'The Care Crafts Project club at Sentinel is a chapter of the international, youth-led organization whose mission is to brighten the days of hospital patients through handmade crafts. We understand that long hospital stays can take an emotional toll on patients, so we hope to help combat those feelings of loneliness, isolation, and depression by donating uplifting crafts like cards with encouraging messages, bracelets, bracelet kits, and crochet items to local care facilities. And as a member, you can be the crafter bringing comfort to someone who needs it. Whether you love arts and crafts, are passionate about healthcare, or want to get involved in charity work, the Care Crafts Project is the perfect place to unleash your creativity while making a real impact!', 'Wednesdays at lunch', 'Room 251', 'Ms. Caine', 'x3krtct2', false),
  ('Careers in Dentistry', 'club', 'Sentinel''s Careers in Dentistry club allows students to explore different aspects of dentistry for their future by connecting with several guest speakers and engaging in our fun activities. Members will also be able to participate in our fundraisers.', 'Biweekly Thursdays at lunch', 'Room 154', 'Ms. Smith', 'e4v74qqd', false),
  ('Careers in Medicine (CIM) Club', 'club', 'CIM is for students passionate about exploring careers in healthcare and medicine. Our focus is on providing career insights, mentorship, and hands-on opportunities for students interested in the medical field. This club serves as a guide for students interested in pursuing medicine, offering insights into career paths, job requirements, relevant programs, and experiences essential for future healthcare professionals. Members connect with mentors in the medical field, gaining exposure to various healthcare careers, current studies, and new technologies. A significant initiative of our club is fundraising for a children’s hospital, which includes organizing research projects and charitable events. We hope to foster a spirit of community involvement and potentially visit the hospital as part of our mission.', 'Fridays at lunch', 'Room 205', 'Ms. S. Armstrong', 'e2l2kd5c', false),
  ('Cat Club', 'club', 'Cat Club was made to encourage people who love cats to do something for cats. Our club will be a platform for your first step to do something for them! Our main focus is to fundraise for animal shelters, adoption centers, and help cats who may not have a warm cozy home. We will do volunteer work with cat organizations like RAPS and SPCA and also do fundraising inside of school to donate! We welcome everyone who wants to do something for them to join!', 'Biweekly Wednesdays at lunch', 'Room 355', 'Mr. Klippenstein', 'wwlsu4sc', true),
  ('Chamber Music Club', 'music', 'The Chamber Music Club is a place for students who enjoy music and want to play together in small groups. We welcome students who play different instruments and have different skill levels. Members will have opportunities to practice chamber music, improve their teamwork and communication skills, and perform together. Our goal is to create a friendly environment where students can share their passion for music and learn from each other.', 'Wednesdays at lunch', 'Music room', 'Mr. Ahmelich', 'Ofmzmqlw', true),
  ('Sentinel Chess Club', 'club', 'Join the Sentinel Chess Club! Whether you’re a beginner or an experienced player, this is the perfect place to sharpen your skills, challenge friends, and enjoy the game of strategy and focus. We''ll be providing opportunities for Spartans to showcase their chess skills with tournaments, workshops, field trips, and much more! Make the move and join the fun!', 'Thursdays at lunch', 'Room 355', 'Mr. Hammett', 'qhoamney', false),
  ('Chinese Culture Club', 'club', 'The Chinese Culture Club celebrates and shares Chinese culture through engaging activities, cultural presentations, traditional games, and creative experiences. Members will have opportunities to explore Chinese traditions, festivals, food, arts, and customs while connecting with others and building cultural appreciation. Our club also hosts a Lunar New Year Celebration inspired by the traditional Chinese Spring Festival Gala, featuring student performances and cultural activities. Everyone is welcome to join us in discovering, appreciating, and celebrating Chinese culture!', 'Mondays at lunch', 'Room 203', 'Ms. Li', 'mk2q7w5', false),
  ('Sentinel Classical Music Club', 'music', null, 'Thursdays at lunch', 'Music room', 'Mr. Virag', null, false),
  ('Comité d''immersion française', 'club', null, 'Wednesdays at lunch', 'Room 304', 'Mme. Morvarid', null, false),
  ('The Composers Club', 'music', 'Are you interested in composing music in a friendly, no pressure environment? Our club is all about having fun, getting together to compose music, learn new things, and meet new people.', 'Tuesdays at lunch', 'Room 202', 'Ms. Chouinard', 'ep5a3nlw', true),
  ('Sentinel Computer Science Club', 'club', 'The Computer Science Club is a welcoming community for students of all skill levels looking to explore programming, computational thinking, and technology. Members will build practical skills through fun daily programming puzzles and coding challenges, get guidance on school computer science course pathways, and prepare together for Sentinel’s CS contests like the Beaver Computing Contest (BCC) and Canadian Computing Contest (CCC). In addition, the club connects members with hands-on technical volunteering opportunities such as refurbishing donated hardware and testing systems with volunteering organizations that lets you gain valuable volunteer hours while learning real world computer skills. Whether you are an experienced programmer or just curious about getting started with technology, join us to connect, collaborate, and grow your computer science skills!', 'Biweekly Day 1 Thursdays at lunch', 'Room 149A', 'Mr. Neufeld', 'nsfmgnlj', false),
  ('Creative Club', 'club', 'Creative Club is a club where you get to expand your brain in creative ways! Imagine cool things, and little to no drawing skills are required! (Unless you can''t draw a stickman, then that''s a problem.) We’ll be doing fun activities and competitions that get your mind thinking, and some activities might have the option to be in a group or not to fit your preference!', 'Twice a month, Fridays at lunch', 'Room 200', 'Ms. Deneau', 'uooqs7jy', false),
  ('Creative Entrepreneurs Network (CEN)', 'club', 'Creative Entrepreneurs Network (CEN) is a club for students who are interested in business, entrepreneurship, and creating handmade products. Members can explore how ideas can be turned into real products or small businesses through hands-on projects, marketing, design, and school holiday sales. Members can also learn about different parts of running a business, from developing ideas and building a brand to selling products and connecting with customers.', 'Biweekly Day 1 Tuesdays at lunch', 'Room 149A', 'Mr. Neufeld', 'zav567sd', false),
  ('Creative Media Club', 'club', null, 'Mondays 7:30–8:15 am', 'Room 310', 'Ms. Gagliano', null, true),
  ('Creative Writing and English Enrichment Club', 'club', 'The English Enrichment Club is a place to strengthen your command of the English language. Our activities include improving word diversity and usage, studying stylistic rules such as repetition or flow, and discussing and creating both fictional and nonfiction literature. Whether you want to expand your vocabulary, refine your writing, or explore literature more deeply, all students are welcome to join.', 'Day 2 Tuesdays at lunch', 'Room 201', 'Mr. Klippenstein', 'xlkrv3ek', true),
  ('CSAIQC Club', 'club', 'Interested in AI, cybersecurity, or quantum computing? The CSAIQC club hosts guest speakers, hackathon prep sessions, and district wide CTF challenges. The club is a great place to build new skills and meet like-minded students!', 'Wednesdays at lunch', 'Room 351', 'M. Mirmiran', 'ackmmydw', true),
  ('Sentinel DEC Club', 'club', null, 'See Google Classroom for dates', 'Room 149A', 'Mr. Neufeld', null, false),
  ('Duke of Edinburgh', 'club', null, 'Once a month at lunch, dates TBD', 'Room 302', 'Mr. Ahmelich & Ms. Britten', 'zq4xgby5', true),
  ('Sentinel Dungeons and Dragons Club', 'club', 'The DND club is focused on running campaigns for tabletop games such as Dungeons & Dragons and Warhammer 40k after school as a service for the school community. We aim to create a positive and welcoming social space and introduce newcomers to tabletop games. We will be running most days after school.', 'Mon–Thu after school, 3:15–5:30', 'Room 154', 'Ms. Smith & Mr. Huh', 'zvakreat', false),
  ('Sentinel Economics Club', 'club', null, 'See Google Classroom for dates', 'Room 258', 'Mr. Demers', null, false),
  ('EmpowerHer', 'club', 'EmpowerHer Club is a student-led club at Sentinel Secondary School dedicated to empowering young women and creating a supportive, inclusive space for students to connect, learn, and have meaningful conversations. We explore topics such as women’s rights, gender equality, representation, education, women and the law, and advocacy, while encouraging members to share their perspectives and develop confidence and leadership skills. Through discussions, awareness initiatives, projects, and community involvement, our goal is to help students understand their voices and use them to create positive change.', 'Two Fridays a month', 'Room 207', 'Ms. S. Armstrong', '4jv7xpwy', true),
  ('Engineering Club', 'club', 'The Engineering Club is for anyone interested in the field of engineering, hands on design, and technical problem solving. Members will learn key engineering tools like Physics, CAD, Computer Science, and Math, while collaborating on major team engineering projects. No prior experience needed. We also offer targeted preparation for high level competitions like the UBC Physics Olympiad, alongside exclusive volunteering opportunities at regional robotics tournaments. Whether you want to build high level mechanical projects, improve your physics skills, or gain real world engineering experience, join us to start thinking and creating like an engineer!', 'Day 1 Tuesdays/Wednesdays at lunch', 'Room 355', 'Mr. Hammett', 'xadzcj6u', false),
  ('Evergrow Org', 'club', null, 'Fridays at lunch', 'Room 154', 'Ms. Smith', null, false),
  ('Sentinel Fashion Club', 'club', null, 'Biweekly Fridays at lunch', 'Room 304', 'Mme. Morvarid', null, false),
  ('Film Club', 'club', 'The Film Club is a place and time to watch, discuss, and review movies, exploring their long history and the meaning behind film.', 'Thursdays after school, 3:15–5:30', 'Room 154', 'Ms. Smith & Ms. Shackleton-Turner', 'nbr6plhx', true),
  ('Financial Literacy Club', 'club', null, 'Mondays at lunch', 'Room 258', 'Mr. Demers', '4vrr2lsn', true),
  ('Sentinel Food and Nutrition Club', 'club', null, 'Mondays at lunch', 'Room 255', 'Ms. Malone', null, false),
  ('Football Club', 'club', 'The Football Club brings students together through a shared interest in American football. Whether you''re an experienced player or completely new to the sport, everyone is welcome to learn, participate, and be part of the club. The club provides opportunities to play touch football, flag football, and enjoy watching NFL games, including the playoffs and Super Bowl.', 'Fridays at lunch', 'Room 201', 'Mr. Klippenstein', 'y75tmqvq', true),
  ('The Garden Gurus', 'club', null, 'Tuesdays at lunch', 'Room 354', 'Ms. Ogawa & Ms. Curtin', null, false),
  ('Generation of Honour Foundation', 'club', 'Generation of Honor is a school-based club that gives students opportunities to make a positive impact in their community. We meet every other week to create care packages, write cards, raise awareness, and share volunteer opportunities. Students can also learn about volunteer opportunities organized by the Generation of Honor Foundation outside of school.', 'Wednesdays at lunch', 'Room 202', 'Ms. Tabone', '5xpac5aw', true),
  ('GSA (Gender and Sexuality Alliance)', 'club', 'We are the GSA club, our goal is to ensure a safe culture here at Sentinel. We believe that growth happens through connection. When we feel like we belong is when we can reach a greater understanding of ourselves and the community that surrounds us.', null, null, 'Ms. Smith', 'yh5ati3o', false),
  ('The Harvest Project Club', 'club', 'The Harvest Project Club is a student-led club focused on giving back to our community and supporting people experiencing food insecurity and financial challenges. Through fundraisers, food drives, volunteering, and awareness campaigns, we work together to make a positive difference. All funds raised by our club are donated directly to Harvest Project to support the important work they do in our community.', 'Day 2 Wednesdays at lunch', 'Room 354', 'Ms. Sinnott', 'jqmy4got', false),
  ('Health and Fitness Club', 'club', 'Our Health and Fitness Club promotes an active lifestyle by getting students involved in the gym, learning about fitness, and helping younger grades feel more comfortable and confident working out.', 'Lunch, day TBD', 'Room 149A', 'Mr. Neufeld', '7rmrk5jc', true),
  ('Health for All', 'club', 'Health for All is a club dedicated to advocating for, and raising awareness about inequities in the healthcare system, as well as addressing the systemic barriers marginalized and underserved communities face when accessing care. We plan to organize fundraising campaigns, supply drives, volunteer opportunities, community events, and more that support local, possibly even global, lesser known organizations working toward health equity. Through workshops, guest speakers, and student-led initiatives, we empower youth to learn, collaborate, and take meaningful action towards a more inclusive healthcare system for all. If you’re passionate about making a real difference, starting right here in our community, join us in advancing equity and building a future where everyone has equal access to quality healthcare.', 'Thursdays at lunch', 'Room 207', 'Ms. S. Armstrong', 'fohcznsa', false),
  ('Health Sciences Club', 'club', 'Explore medicine, psychology, global health, and healthcare tech like CRISPR! Join us for bi-weekly lunch discussions, creative media projects, and a clinician interview series. No prior medical knowledge required — all grades welcome!', 'Wednesdays at lunch', 'Room 361', 'Ms. Ogawa', 'ryjzdrmb', false),
  ('Helping Hearts', 'club', 'Helping Hearts Youth Foundation at Sentinel is focused on turning students’ ideas into meaningful community impact. Built around changemaking, friendship, and innovation, members lead projects, fundraisers, advocacy campaigns, and service initiatives while building connections with other students. The club encourages students to take initiative, collaborate, and develop creative solutions to real-world issues. At Sentinel, members meet weekly and have opportunities to lead projects and make a difference.', 'Mondays or Fridays at lunch', 'Room 208', 'Ms. Page-Newman', 'noo7anzz', false),
  ('History Club', 'club', 'Our club is a space for history enthusiasts to gather, discuss historical events, and participate in interactive activities while exploring their relevance to today''s world. Join us for engaging conversations, interactive lessons, fun historical roleplay and opportunities to compete in the International History Bee and Bowl (IHBB) and other events. Whether you''re passionate about ancient civilizations, modern political movements or just want to have fun and learn new things, there''s a place for you to discuss, learn, socialize, and share your knowledge in a fun, inclusive environment. Everyone is welcome; no prior experience required!', 'Fridays at lunch', 'Portable 2', 'Mr. Elliot', 'hvl4q4x', false),
  ('HOSA Medical Club', 'club', 'Are you interested in a career in healthcare? HOSA – Future Health Professionals is a club dedicated to preparing the next generation of healthcare workers. As a member, you get to hear from guest speakers in diverse medical fields, compete in national and international conferences, and develop practical skills such as first aid through interactive workshops. Members can also make a difference in the community by participating in fundraisers for local hospitals. With over 30 competitive events spanning individual and team challenges, HOSA offers something for everyone, whether you are passionate about nursing, dental science, behavioral health, or veterinary science!', 'Biweekly Mondays at lunch', null, 'Mr. Gage', 'xnrfgbzl', true),
  ('Key Club', 'club', 'Key Club International is a student-led organization dedicated to leadership, community service, and making a positive impact. At Sentinel, Key Club provides students with opportunities to give back through volunteering, fundraising, and community initiatives. Members develop leadership skills, build meaningful connections, and work together to support those in need. Whether you’re looking to gain volunteer experience, meet new people, or make a difference, Key Club is a great place to get involved! Everyone is welcome, and no prior volunteer experience is needed!', 'Tuesdays at lunch', null, 'Ms. Rinon', 'vgybnoou', false),
  ('Sentinel K-POP Dance Club', 'club', 'The Sentinel K-POP Dance Club aims to bring together students who are passionate about K-POP dance and culture. Our objective is to create a fun and exciting community where students can build confidence, community, and charisma through practicing and performing K-POP dance covers. We will also film and share our projects and performances on Instagram and TikTok, host random play dances, dance workshops, and other K-POP events, and showcase live performances at school and community events.', null, null, null, 'lbwkkhf', false),
  ('Law Club', 'club', 'Interested in law or becoming a lawyer? Join the Sentinel Law Club to explore different fields of law, famous court cases, current legal issues, and hear from guest speakers in the legal field. Whether you’re thinking about pursuing a career in law or just want to learn more, everyone’s welcome!', 'Tuesdays at lunch', 'Room 156', 'Mr. Chase', 'n7kqf4sj', false),
  ('Le Cercle Français', 'club', null, 'Wednesdays or Thursdays at lunch', 'Room 310', 'Ms. Gagliano', null, true),
  ('Life Sciences Club', 'club', null, null, 'Room 351', 'M. Mirmiran', null, false),
  ('Sentinel Marketing Club', 'club', 'The Marketing Club is a space to explore different ways marketing is used to promote ideas, businesses, products, and events. Throughout the year, the club will work on projects such as promoting school events and clubs, creating promotional materials and social media content, and developing marketing campaigns. Club members will also have the opportunity to take part in projects involving local businesses and organizations, where they can put their ideas into practice and experience different aspects of marketing. The club will provide a chance to learn, experiment with different ideas, and work together on creative projects.', 'Wednesdays at lunch', 'Room 252', 'Mr. Neufeld', 'xj5vmh5', false),
  ('Model United Nations Club', 'club', 'The Sentinel Model UN club is where you can hone your public speaking, diplomacy, and negotiation skills. Every year, we will form delegations to attend Vancouver''s largest conferences and hold weekly meetings to equip you with the skills to engage in the debate and compromise that is signature to the world of Model UN. If you have ever been interested in politics, international relations, or even public policy, this is the perfect club for you.', 'Mondays at lunch', 'Room 156', 'Mr. Chase', 'fsk3a2ni', false),
  ('Music Foundations Club', 'music', 'Never had the chance to learn an instrument? Music Foundations Club is for you. Each month we explore a new instrument and a new genre: you''ll see it played live, learn how it works, and find out where it came from. No experience or instrument needed, just curiosity.', 'Fridays at lunch', 'Music room', 'Mr. Virag', null, true),
  ('The NextGen Health Educators', 'club', null, 'Day 1 Wednesdays at lunch', 'Room 354', 'Ms. Sinnott', null, true),
  ('Otaku Club', 'club', 'The Otaku Club exists to foster joy, enthusiasm, and community among students who love anime, manga, manhwa, otaku games, and Japanese/Korean/Chinese pop culture. Our mission is to create a fun, inclusive, and safe space where otakus can gather, share, learn, and geek out together.', 'Mondays at lunch', 'Portable 1', 'Mr. Huh', 'ofwlppzw', false),
  ('PATH Careers Club', 'club', 'Curious about what you could do after high school? PATH invites professionals from a wide range of careers to talk about how they got where they are, from medicine and law to trades, architecture, and entrepreneurship. Come hear real career stories, ask questions, and explore options you might not have thought of. All grades are welcome.', 'Day 1 lunches, twice a month', 'Room 201', 'Mr. Ahmelich', '74gpt22l', false),
  ('Photography Club', 'club', 'Join Photography Club to learn the basics of photography, hear from guest speakers, enter photo competitions, and take part in volunteer opportunities. Cameras and Lightroom will be provided, so no experience or equipment is needed!', 'Every second Friday at lunch', 'Room 153A', 'Ms. Tabone', 'ethh2lia', true),
  ('Pickleball Club', 'club', null, null, 'Room 201', 'Mr. Klippenstein', null, true),
  ('The Positivity Project', 'club', null, 'Biweekly Tuesdays at lunch', 'Room 153A', 'Ms. Tabone', '6oakaye4', true),
  ('Project Pearly Whites', 'club', 'Project Pearly Whites is a club dedicated to promoting dental health, improving oral hygiene awareness, and giving back to our community. We aim to educate students about the importance of oral health, create and distribute “Smile Kits” containing essential dental care supplies, organize hygiene product drives, and support local shelters through fundraising initiatives. Our goal is to bring healthier smiles to our community while inspiring students to make a difference.', 'Mondays at lunch', 'Room 361', 'Mr. Grikis', 'wrerpuan', true),
  ('Psychology Club', 'club', 'Interested in why people think, feel, and act the way they do? Join Psychology Club! We explore everything from personality and relationships to mental health, social behaviour, and the brain through discussions, activities, and real-world psychology. Whether you''ve already learned about psychology or are just curious about people, everybody''s welcome!', 'Biweekly Fridays at lunch', 'Room 354', 'Ms. Ogawa', 'q6tfchv', false),
  ('Rare Medical Conditions Awareness Club', 'club', null, 'Biweekly Thursdays at lunch', 'Room 361', 'Ms. Ogawa', null, true),
  ('Robotics Club', 'club', 'Ever wanted to build an electronic product? Ever wondered how electronic devices actually work? Join us! We''re a brand new club focused on microcontrollers and sensor robotics, working with computer chips like the ESP32, STM32, and Raspberry Pi. All parts are provided so there is no cost to members! Everyone starts from scratch here, and we''re completely beginner friendly. At the end of the year, we''re running a robotics competition with a really big prize pool. Since we have no veterans, everyone gets a completely fair shot at winning. Come join us today and maybe win something along the way!', 'Twice a month after school, dates TBD', 'Room 351', null, 'svn56kp6', true),
  ('Science Fair Club', 'club', 'The science club exists to help students design, build & present original science fair projects. Through structured meetings, hands-on feedback & troubleshooting sessions, our goal is to explain the scientific method and give students the support they need to finish with a strong project for fairs like GVRSF.', 'Biweekly Tuesdays at lunch', 'Room 358', 'Ms. Sinnott', 'alj4ee7h', true),
  ('Screen Production Club', 'club', null, 'Thursdays at lunch', 'Theatre', 'Ms. McGuinness-Gill', null, false),
  ('Self-Restoration Club', 'club', null, 'Lunch, day TBD', null, 'Mr. Neufeld', null, true),
  ('Sentinel Emergency Team', 'club', 'Sentinel Emergency Team (SET) is a student volunteer group made up of members certified in first aid. Dedicated to campus safety, SET provides first aid support, assists during campus events, and helps ensure a safe environment for every student at Sentinel.', null, null, 'Ms. Ulinder', 'htnhnd65', false),
  ('SnowGlobe Initiative', 'club', 'SnowGlobe Initiative Sentinel is the Sentinel Secondary School chapter of SnowGlobe Initiative, a youth-led nonprofit organization dedicated to promoting sustainability, reducing plastic waste, and empowering young people to take action on environmental issues. As a school chapter, we aim to bring the SnowGlobe Initiative''s mission into our school community by raising awareness about pressing environmental challenges and encouraging students to turn their knowledge into meaningful action. We plan to organize interactive workshops, fundraising campaigns, recycling and waste-reduction programs, community cleanups, educational events, and volunteer opportunities that extend our impact beyond the classroom. Through these student-led initiatives, we hope to provide members with opportunities to develop their leadership skills, collaborate with peers who share similar interests, and contribute to a more environmentally conscious community. Whether you''re passionate about environmental advocacy, interested in organizing fun and creative projects, or simply looking to make a positive difference, join us in turning small actions into lasting change!', 'Tuesdays at lunch', 'Room 252', 'Mr. Gage', 'bvxcyemt', true),
  ('Social Data Club', 'club', 'Our club explores social psychology and student interests through monthly experiments and survey-based research. Each month, members help select a topic, design and conduct experiments, collect survey responses through Google Forms, organize and analyze data, and turn the findings into clear research reports. Our reports are shared through WeChat and Instagram to make psychology and data analysis more accessible and engaging. Through these activities, members gain hands-on experience in social psychology research, experimental design, data analysis, teamwork, and scientific communication.', 'Tuesdays at lunch', 'Portable 1', 'Mr. Huh', 'shjuhwl5', false),
  ('Sociology Club', 'club', 'The sociology club is dedicated to helping members understand the development and functioning of modern society, exploring culture, identity, social context, behaviour, and systems along the way. Our goal is to help students see the world differently, with a strong focus on applying that understanding through direct service & community engagement.', 'Biweekly Thursdays at lunch', 'Room 149B', 'Mr. Fromowitz', 'vkxu2lc5', false),
  ('Spartan X Sports', 'club', null, 'Biweekly or monthly Fridays at lunch', 'Gym / Field house', 'Mr. Klippenstein', null, true),
  ('Spartans App Club', 'club', 'Spartans App Club runs the official school app! Build and maintain the official app of your school, learn how to develop real apps in the modern world, and put a tangible project on your resume. We have a variety of different club member roles for different aspects of the app process; maintenance, development, creativity, badges, advertising, etc. No matter your skill set there is a role for you!', 'Fridays at lunch', 'Room 149A', 'Mr. Neufeld', 'brfxwyka', true),
  ('Speech and Debate Club', 'club', 'Interested in public speaking, winning awards, or discussing social issues? Join the Speech & Debate Club today to learn how to persuade anyone to do anything as we compete at tournaments on both a local and international level. Whether you want to improve your English essay writing skills or convince your parents to let you skip class, there is a place for everyone at the podium here.', 'Wednesdays at lunch', 'Room 203', 'Mr. Fuller', 'tqlre4m', false),
  ('STEM Club', 'club', 'Interested in science, technology, engineering, and math? Join STEM Club to explore real-world ideas, work on hands-on projects, learn about different fields of STEM, and collaborate with other students. Whether you already have a passion for STEM or know it as a buzzword from social media, come join us and learn more, everyone is welcome!', 'Fridays at lunch', 'Room 351', 'M. Mirmiran', 'gp4ddif5', false),
  ('Stop the Traffic Initiative', 'club', 'Stop The Traffic is a student led initiative dedicated to reducing traffic here at Sentinel. Join our diligent team of volunteers to guide traffic to alternative drop-off locations and incentivise the use of alternative transportation methods (ATM) through our Monthly Blitzes. Hours are from 8:00 AM to 8:25 AM (more details in Google Classroom), and count towards graduation requirement & school service hours! No prior volunteering experience is required.', 'Some Wednesdays at lunch', 'Room 304', 'Mr. Anderson', 'dwaeooa4', false),
  ('The StrongHer Society', 'club', null, 'Biweekly Fridays at lunch', 'Room 154', 'Ms. Smith', null, true),
  ('Sentinel Streamkeepers', 'club', 'The Sentinel Streamkeepers club focuses on protecting and monitoring salmon and their stream habitats. Through weekly surveys with the West Vancouver Streamkeepers society, we raise awareness and educate others about environment protection.', 'Wednesdays after school (surveys)', null, 'Ms. Smith', 'obh3uxy2', false),
  ('Super Smash Bros Ultimate Club', 'club', null, 'Wednesdays at lunch', 'Room 366', 'Mr. Addis', null, false),
  ('Sentinel Truth & Reconciliation Council', 'club', null, 'Fridays at lunch', 'Portable 2', 'Mr. Elliot', null, false),
  ('Sentinel Volunteers Club', 'club', 'Interested in volunteering but not sure where to start? Here at the Sentinel Volunteers Club (S.V.C) we host meetings every other Tuesday at lunch to share all the tips and tricks from experienced volunteers, group expeditions (where we volunteer in school and out in the community together as a club), Pringle & Mingle Meetings to celebrate club milestones and participate in fun bonding activities. If you''re interested in gaining volunteer hours and supporting the community with friends and mentors, come join us at S.V.C!!', 'Biweekly Tuesdays at lunch', 'Room 358', 'Ms. Alm & Ms. Ogawa', 'bx2epesv', false),
  ('The Wheel Deal', 'club', null, 'Mon, Thu, Fri after school, 3:00–5:00', 'Room 153C', 'Ms. Evans', null, false),
  ('Women''s Sports Mentoring Program', 'club', 'The Women’s Sports Mentoring Club (WSMC) empowers women to lead, excel, and break barriers through sports. We aim to inspire a lifelong passion for athletics, cultivate grit and confidence in girls, and foster the next generation of female leaders in our Sentinel community.', 'Fridays at lunch', 'Room 202', 'Ms. Chouinard & Ms. Sinnott', 'ejyxgz75', true),
  ('World Scholar''s Cup Club', 'club', 'A club based on the World Scholar''s Cup, where everyone can learn interesting, trivial topics and practice showing their knowledge! Including learning new facts, speaking, and writing.', 'Thursdays at lunch', 'Room 206', 'Mr. McLean', 'lixcy62e', false),
  ('YHOPE Foundation', 'club', 'Join us to raise awareness about youth mental health, plan events, and make a real impact in our school and community.', 'Once a month, dates TBD', 'Room 156', 'Mr. Chase', 'ruwrzvub', true),
  ('Youth Action for Change Club', 'club', null, 'Biweekly Mondays at lunch', 'Room 202', 'Ms. Chouinard', null, false),
  ('YPC Sentinel Branch', 'club', 'Engages local students in youth-led grant-making, community projects, and leadership focused on mental health, the environment, and inclusivity.', 'Once a month, day TBD', 'Room 304', 'Mme. Morvarid', 'meux7t43', true)
), updated as (
  update clubs c set kind = v.kind, blurb = v.blurb, meets = v.meets, room = v.room,
    sponsor = v.sponsor, gc_code = v.gc_code, is_new = v.is_new, active = true
  from v where lower(trim(c.name)) = lower(trim(v.name))
  returning c.id
)
insert into clubs (name, kind, blurb, meets, room, sponsor, gc_code, is_new)
select v.name, v.kind, v.blurb, v.meets, v.room, v.sponsor, v.gc_code, v.is_new from v
where not exists (select 1 from clubs c where lower(trim(c.name)) = lower(trim(v.name)));
